def wildcard_word_matching(words, queries):
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = True

    def match(node, q, i):
        if i == len(q):
            return node.get("$", False)
        ch = q[i]
        if ch == ".":
            for k, child in node.items():
                if k == "$":
                    continue
                if match(child, q, i + 1):
                    return True
            return False
        if ch in node:
            return match(node[ch], q, i + 1)
        return False

    return [match(root, q, 0) for q in queries]
